// Mengambil data berdasarkan nama node kamu di screenshot
const budgets = $('get_budget').all().map(i => i.json);
const transactions = $('get_expenses').all().map(i => i.json);

// 1. Simpan batas budget per kategori
const budgetMap = {};
for (const b of budgets) {
  if (b.category && b.monthly_limit) {
    budgetMap[b.category.toString().trim()] = Number(b.monthly_limit) || 0;
  }
}

// 2. Format Tanggal Hari Ini & Bulan Ini
const now = new Date();
const todayStr = now.toISOString().split('T')[0];
const currentMonthStr = todayStr.substring(0, 7); // Format: YYYY-MM

let todayExpense = 0;
let monthExpense = 0;
let monthIncome = 0;
let categoryTotals = {};

// 3. Agregasi Transaksi
for (const row of transactions) {
  const date = (row.date || '').toString().trim();
  const type = (row.type || '').toLowerCase().trim();
  const value = Number(row.value) || 0;
  const category = (row.category || 'Others').toString().trim();

  // Rekap Bulan Ini
  if (date.startsWith(currentMonthStr)) {
    if (type === 'expense') {
      monthExpense += value;
      categoryTotals[category] = (categoryTotals[category] || 0) + value;
    } else if (type === 'income') {
      monthIncome += value;
    }
  }

  // Rekap Hari Ini
  if (date === todayStr && type === 'expense') {
    todayExpense += value;
  }
}

const formatRp = (num) => 'Rp ' + Number(num).toLocaleString('id-ID');

// 4. QuickChart Doughnut
const labels = Object.keys(categoryTotals);
const data = Object.values(categoryTotals);

let chartUrl = '';
if (labels.length > 0) {
  const chartConfig = {
    type: 'doughnut',
    data: {
      labels: labels,
      datasets: [{
        data: data,
        backgroundColor: ['#6366F1', '#EC4899', '#10B981', '#F59E0B', '#8B5CF6', '#3B82F6', '#EF4444']
      }]
    },
    options: {
      plugins: {
        title: { display: true, text: `Pengeluaran ${currentMonthStr}` }
      }
    }
  };
  chartUrl = `https://quickchart.io/chart?c=${encodeURIComponent(JSON.stringify(chartConfig))}&w=500&h=300&bkg=white`;
}

// 5. Susun Pesan HTML Telegram

// Ganti bagian pembentukan 'message' di script Code Node:
let budgetText = 'Belum ada catatan pengeluaran bulan ini.';

if (labels.length > 0) {
  const budgetLines = [];
  for (const cat of labels) {
    const spent = categoryTotals[cat];
    const limit = budgetMap[cat] || 0;

    if (limit > 0) {
      const pct = Math.round((spent / limit) * 100);
      const icon = pct >= 100 ? '🚨' : pct >= 80 ? '⚠️' : '✅';
      budgetLines.push(`${icon} ${cat}: ${formatRp(spent)} / ${formatRp(limit)} (${pct}%)`);
    } else {
      budgetLines.push(`• ${cat}: ${formatRp(spent)} (Tanpa limit)`);
    }
  }
  budgetText = budgetLines.join('\n');
}

const chartSection = chartUrl ? `\n📊 Grafik Pengeluaran:\n${chartUrl}` : '';

// String multiline murni tanpa \n manual:
const message = `🌙 LAPORAN HARIAN & REKAP KEUANGAN
━━━━━━━━━━━━━━━━━━━━━
📅 Tanggal: ${todayStr}
💸 Pengeluaran Hari Ini: ${formatRp(todayExpense)}

📊 RINGKASAN BULAN INI (${currentMonthStr})
├ 📈 Total Masuk: ${formatRp(monthIncome)}
├ 📉 Total Keluar: ${formatRp(monthExpense)}
└ 💎 Saldo Sisa: ${formatRp(monthIncome - monthExpense)}

🎯 MONITORING ANGGARAN
${budgetText}${chartSection}`;

return [{ json: { message, chat_id: 1644304302 } }];
